/* AIVIC_FUNCTION_BUNDLE_START owner=determineReportDelay exports=determineReportDelay */
const __aivicBundle_68_determineReportDelay = (() => {
  function determineReportDelay(input: {
    reportSubmissionTime: Date;
    morningMeetingStartTime: Date;
    employeeId?: string;
  }): {
    isOnTime: boolean;
    isDelayed: boolean;
    delayMinutes: number;
    status: string;
  } {
    const submissionTime = input.reportSubmissionTime.getTime();
    const meetingTime = input.morningMeetingStartTime.getTime();
    const delayMs = submissionTime - meetingTime;
    const delayMinutes = Math.max(0, Math.ceil(delayMs / (1000 * 60)));
  
    const isDelayed = submissionTime > meetingTime;
    const isOnTime = !isDelayed;
  
    let status: string;
    if (isOnTime) {
      status = '時間内';
    } else {
      status = '遅延';
    }
  
    return {
      isOnTime,
      isDelayed,
      delayMinutes,
      status,
    };
  }
  return { determineReportDelay };
})();
export const determineReportDelay = __aivicBundle_68_determineReportDelay.determineReportDelay;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineReportDelay */

